insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_livelihood','livelihood','noun','the work or activity that a person depends on to earn money for living','[{"senseId":"livelihood_1","meaning":"the work or activity that a person depends on to earn money for living","acceptedParaphrases":["means of earning a living","source of income"],"masteryContexts":[{"contextId":"u4_31_livelihood_meaning","text":"Many taxi drivers depend on tourism for their livelihood.","meaning":"the way a person earns money to live","wrongMeanings":["the way a person spends money on holiday","the way a person travels between home and work","the way a person pays tax each year"]},{"contextId":"u4_31_livelihood_paraphrase","text":"When the ferry service closed, hundreds of dockworkers lost their livelihood.","meaning":"the work that a person depends on for an income","wrongMeanings":["the training that a person receives for a job","the union that a person joins at work","the home that a person rents near work"]}],"situationDistractors":["The family spent the weekend at a beach resort and relaxed in the sun.","The manager moved to a larger office on the top floor of the building.","The tourists asked the guide where they could buy a cup of coffee.","The taxi driver carried the suitcases to the hotel entrance.","The ferry left the harbour at noon with two hundred people on board.","A cyclist stopped beside the road to fix a puncture."],"gapDistractors":[{"contextId":"u4_31_livelihood_gap_1","answer":"livelihood","wrong":["hobby","uniform","fashion"]},{"contextId":"u4_31_livelihood_gap_2","answer":"livelihood","wrong":["holiday","uniform","neighbour"]},{"contextId":"u4_31_livelihood_gap_3","answer":"livelihood","wrong":["holiday","uniform","weekend"]}],"spellingErrors":["livlihood","livelyhood","liveliehood","livelihod","livilihood","livelhood"],"masteryPassages":[{"passageId":"u4_31_livelihood_passage_1","contextId":"u4_31_livelihood_gap_1","text":"The new bypass will take traffic away from the village. Local shopkeepers fear that fewer customers will damage their ____.","answer":"livelihood"},{"passageId":"u4_31_livelihood_passage_2","contextId":"u4_31_livelihood_gap_2","text":"In many coastal towns, tourism is the only way to earn a living. When storms stopped the ferries for a month, boat owners and guides lost their ____.","answer":"livelihood"}],"contextDependentParaphrases":[],"wrongParaphrases":["amount of money earned","position held in a company","style of everyday life"],"misleadingDistractors":["the amount of money a person is paid each month","the particular position a person holds in a company","the way a person chooses to live and spend free time"]}]'::jsonb,'[]'::jsonb,'["earn a livelihood","means of livelihood","lose their livelihood"]'::jsonb,'live'),
('vocab_fatality','fatality','noun','a death caused by an accident, disaster or similar event','[{"senseId":"fatality_1","meaning":"a death caused by an accident, disaster or similar event","acceptedParaphrases":["death","loss of life"],"masteryContexts":[{"contextId":"u4_32_fatality_meaning","text":"Fortunately, the minor crash at the roundabout caused no fatality, only some damage to the vehicles.","meaning":"a death caused by an accident","wrongMeanings":["an injury caused by an accident","a delay caused by an accident","a fine caused by an accident"]},{"contextId":"u4_32_fatality_paraphrase","text":"Each fatality on the railway is recorded in an official report so that safety can be improved.","meaning":"a death in an accident or disaster","wrongMeanings":["a person who survives an accident or disaster","a warning given before an accident or disaster","a loss of money in an accident or disaster"]}],"situationDistractors":["A cyclist fell off her bike and bruised her knee, but she was able to walk home.","The bus was delayed for an hour after the driver took a wrong turning.","Rescue workers helped everyone leave the damaged ferry safely.","The guide gave everyone a map of the old harbour and explained the timetable.","The ticket machine at the station accepted only coins.","A mechanic checked the oil and filled the tank with petrol."],"gapDistractors":[{"contextId":"u4_32_fatality_gap_1","answer":"fatality","wrong":["delay","complaint","mistake"]},{"contextId":"u4_32_fatality_gap_2","answer":"fatality","wrong":["festival","holiday","picnic"]},{"contextId":"u4_32_fatality_gap_3","answer":"fatality","wrong":["holiday","festival","promotion"]}],"spellingErrors":["fatalty","fatallity","fatilty","fatelity","fatalitty","fataliti"],"wordFamilyForms":[{"form":"fatality","partOfSpeech":"noun","example":"Investigators confirmed that there had been only one fatality in the crash.","pedagogicallyUseful":true},{"form":"fatal","partOfSpeech":"adjective","example":"Tiredness is a common cause of fatal accidents on long journeys.","pedagogicallyUseful":true,"altExample":"Drivers who fall asleep at the wheel risk a fatal crash."},{"form":"fatally","partOfSpeech":"adverb","example":"The lorry driver was fatally injured in the crash, the police confirmed.","pedagogicallyUseful":true,"altExample":"Sadly, the cyclist was fatally injured when a van hit her."}],"masteryPassages":[{"passageId":"u4_32_fatality_passage_1","contextId":"u4_32_fatality_gap_1","text":"The charity reported that road accidents are a major cause of death among young people in the region. Each ____ on the roads is a tragedy for a family and a community.","answer":"fatality"},{"passageId":"u4_32_fatality_passage_2","contextId":"u4_32_fatality_gap_2","text":"The new safety system has transformed the railway. In the last decade there has not been a single ____, although millions of passengers use the trains every day.","answer":"fatality"}],"contextDependentParaphrases":[],"wrongParaphrases":["injury","delay","fine"],"misleadingDistractors":["an injury that heals after a few weeks","a person who is hurt in an accident","a report written after an accident"]}]'::jsonb,'["fatal","fatally"]'::jsonb,'["road fatality","fatality rate","single fatality"]'::jsonb,'live'),
('vocab_initiative','initiative','noun','a new plan or action intended to solve a problem or improve a situation','[{"senseId":"initiative_1","meaning":"a new plan or action intended to solve a problem or improve a situation","acceptedParaphrases":["scheme","programme"],"masteryContexts":[{"contextId":"u4_33_initiative_meaning","text":"The government has announced a new initiative to make roads safer near schools.","meaning":"a new plan to solve a problem","wrongMeanings":["a new law to punish drivers","a new report about school children","a new building near a school"]},{"contextId":"u4_33_initiative_paraphrase","text":"The bus company’s latest initiative offers free travel to students on Sundays.","meaning":"a new action intended to improve a situation","wrongMeanings":["a new rule intended to limit a service","a new ticket intended to raise prices","a new complaint intended to stop a change"]}],"situationDistractors":["The school was closed for the holidays, and the playground was empty.","The traffic officer waved the cars forward when the lights failed.","A group of tourists took a photograph in front of the old station.","The ferry captain welcomed everyone on board and pointed out the lifeboats.","A mechanic changed a wheel while the family waited beside the road.","The air steward served drinks and then collected the empty cups."],"gapDistractors":[{"contextId":"u4_33_initiative_gap_1","answer":"initiative","wrong":["timetable","festival","engine"]},{"contextId":"u4_33_initiative_gap_2","answer":"initiative","wrong":["complaint","timetable","festival"]},{"contextId":"u4_33_initiative_gap_3","answer":"initiative","wrong":["argument","exercise","accident"]}],"spellingErrors":["initative","inititive","intiative","initiatve","inisiative","initaitive"],"masteryPassages":[{"passageId":"u4_33_initiative_passage_1","contextId":"u4_33_initiative_gap_1","text":"Too many pupils were being driven to school, which caused heavy traffic at the gates. So the head teacher started a walking ____ in which parents and children meet and walk together.","answer":"initiative"},{"passageId":"u4_33_initiative_passage_2","contextId":"u4_33_initiative_gap_2","text":"The city had a serious problem with air pollution. In response, the mayor announced a bold new ____ to encourage cycling and public transport.","answer":"initiative"}],"contextDependentParaphrases":[],"wrongParaphrases":["complaint","invoice","permit"],"misleadingDistractors":["the ability to make decisions without being told what to do","a speech given at the start of a meeting","the first lesson in a training course"]}]'::jsonb,'[]'::jsonb,'["new initiative","government initiative","local initiative"]'::jsonb,'live'),
('vocab_campaign','campaign','noun','an organised series of actions intended to achieve a particular result, such as changing public behaviour','[{"senseId":"campaign_1","meaning":"an organised series of actions intended to achieve a particular result, such as changing public behaviour","acceptedParaphrases":["public-awareness drive","planned series of actions"],"masteryContexts":[{"contextId":"u4_34_campaign_meaning","text":"The charity started a campaign to persuade cyclists to wear helmets.","meaning":"a series of actions planned to achieve a result","wrongMeanings":["a single announcement made to the press","a long journey made by a group of cyclists","a race held between rival cycling clubs"]},{"contextId":"u4_34_campaign_paraphrase","text":"Thanks to a successful campaign, the council agreed to build a new crossing outside the school.","meaning":"organised public action to achieve a change","wrongMeanings":["a formal complaint made to a court","a private meeting held with a council","a long delay caused by a council"]}],"situationDistractors":["The driver switched on the radio and sang along to his favourite song.","A single officer stood at the junction and waved cars through.","The engineers worked late to repair the bridge, then went home.","The tourists photographed the old castle from the harbour wall.","The ferry arrived at the port and the passengers walked off slowly.","The coach driver stopped at a service area so that the travellers could stretch their legs."],"gapDistractors":[{"contextId":"u4_34_campaign_gap_1","answer":"campaign","wrong":["bridge","timetable","engine"]},{"contextId":"u4_34_campaign_gap_2","answer":"campaign","wrong":["journey","timetable","tunnel"]},{"contextId":"u4_34_campaign_gap_3","answer":"campaign","wrong":["timetable","journey","holiday"]}],"spellingErrors":["campain","campaing","campagn","campiagn","kampaign","campaigne"],"masteryPassages":[{"passageId":"u4_34_campaign_passage_1","contextId":"u4_34_campaign_gap_1","text":"Too many drivers were using their mobile phones at the wheel. So the government started a television ____ showing how quickly an accident can happen.","answer":"campaign"},{"passageId":"u4_34_campaign_passage_2","contextId":"u4_34_campaign_gap_2","text":"Local cyclists wanted a protected lane on the busy main road. They collected signatures, wrote to the council and held a public meeting as part of their ____.","answer":"campaign"}],"contextDependentParaphrases":[],"wrongParaphrases":["road-building project","ticket-selling system","traffic-control device"],"misleadingDistractors":["a long fight between two armies","a short speech given at a public meeting","a plan for the route of a journey"]}]'::jsonb,'[]'::jsonb,'["road safety campaign","launch a campaign","public campaign"]'::jsonb,'live'),
('vocab_pothole','pothole','noun','a hole in the surface of a road caused by wear or damage','[{"senseId":"pothole_1","meaning":"a hole in the surface of a road caused by wear or damage","acceptedParaphrases":["hole in the road","damaged patch of road"],"masteryContexts":[{"contextId":"u4_35_pothole_meaning","text":"A deep pothole in the middle of the lane damaged two tyres on the same afternoon.","meaning":"a hole in a road surface caused by damage","wrongMeanings":["a pool of water that forms beside a road","a bump that is built to slow traffic down","a trench that is dug to repair a pipe"]},{"contextId":"u4_35_pothole_paraphrase","text":"The council promised to fill every pothole on the main road before the end of the month.","meaning":"a damaged hole in a road","wrongMeanings":["a small bridge over a road","a painted line along a road","a metal cover over a drain"]}],"situationDistractors":["The road had just been resurfaced, and the new tarmac was smooth and black.","A fallen tree blocked the lane until workers arrived with a saw.","Workers dug a trench beside the pavement to lay new cables.","The tourists queued at the ticket office to buy tickets for the evening train.","The pilot spoke to the control tower and checked the weather report.","The guide held up a map and pointed at the harbour."],"gapDistractors":[{"contextId":"u4_35_pothole_gap_1","answer":"pothole","wrong":["tunnel","village","holiday"]},{"contextId":"u4_35_pothole_gap_2","answer":"pothole","wrong":["bridge","junction","tunnel"]},{"contextId":"u4_35_pothole_gap_3","answer":"pothole","wrong":["holiday","weather","accident"]}],"spellingErrors":["potthole","pothol","poothole","pothoole","potehole","pothoel"],"masteryPassages":[{"passageId":"u4_35_pothole_passage_1","contextId":"u4_35_pothole_gap_1","text":"After a hard winter, the main road was in terrible condition. Cars bumped from side to side as drivers tried to avoid every ____ in the surface.","answer":"pothole"},{"passageId":"u4_35_pothole_passage_2","contextId":"u4_35_pothole_gap_2","text":"A small crack in the tarmac let rainwater seep underneath. When the water froze and thawed, the crack grew until it became a deep ____ that damaged several tyres.","answer":"pothole"}],"contextDependentParaphrases":[],"wrongParaphrases":["bump in the road","sign beside the road","bend in the road"],"misleadingDistractors":["a deep hole that is dug for pipes or cables","a long crack that runs along the edge of a road","a pond or pool of water beside a road"]}]'::jsonb,'[]'::jsonb,'["deep pothole","fill a pothole","repair a pothole"]'::jsonb,'live'),
('vocab_trauma','trauma','noun','a serious physical or emotional effect caused by a shocking or dangerous event','[{"senseId":"trauma_1","meaning":"a serious physical or emotional effect caused by a shocking or dangerous event","acceptedParaphrases":["lasting distress","deep shock"],"masteryContexts":[{"contextId":"u4_36_trauma_meaning","text":"Witnessing a serious accident can cause trauma that lasts for months.","meaning":"a lasting emotional shock","wrongMeanings":["a short feeling of excitement","a minor injury to the body","a sense of boredom after a long wait"]},{"contextId":"u4_36_trauma_paraphrase","text":"The school arranged support for pupils to help them cope with the trauma of the bus accident.","meaning":"a serious emotional effect caused by a shocking event","wrongMeanings":["a serious delay caused by an unexpected event","a serious cost caused by an expensive event","a serious illness caused by an infection"]}],"situationDistractors":["The passengers enjoyed the calm crossing and watched dolphins from the deck.","The driver felt tired after the long journey and stopped for a rest.","The bus arrived on time, and everyone went straight home.","The mechanic changed the tyres and checked the brakes before the long drive.","The cyclist put on a helmet and fixed a light to the front of the bike.","The guide handed out maps and explained the plan for the day."],"gapDistractors":[{"contextId":"u4_36_trauma_gap_1","answer":"trauma","wrong":["cost","noise","speed"]},{"contextId":"u4_36_trauma_gap_2","answer":"trauma","wrong":["boredom","fashion","noise"]},{"contextId":"u4_36_trauma_gap_3","answer":"trauma","wrong":["cold","price","distance"]}],"spellingErrors":["trama","traumma","trauna","trawma","traumer","tramua"],"masteryPassages":[{"passageId":"u4_36_trauma_passage_1","contextId":"u4_36_trauma_gap_1","text":"Emergency workers often arrive first at the scene of a serious accident. Afterwards, many of them talk to a counsellor to help them deal with the ____ of what they have seen.","answer":"trauma"},{"passageId":"u4_36_trauma_passage_2","contextId":"u4_36_trauma_gap_2","text":"The school bus accident was frightening, although nobody was seriously hurt. For several weeks, some of the children found it difficult to travel by road because of the ____ they had experienced.","answer":"trauma"}],"contextDependentParaphrases":[],"wrongParaphrases":["brief excitement","physical strength","daily routine"],"misleadingDistractors":["a physical illness that spreads quickly","a feeling of tiredness after a long journey","a sense of pride after an achievement"]}]'::jsonb,'[]'::jsonb,'["emotional trauma","cope with trauma","psychological trauma"]'::jsonb,'live'),
('vocab_measures','measures','noun','actions taken to achieve a result or deal with a problem','[{"senseId":"measures_1","meaning":"actions taken to achieve a result or deal with a problem","acceptedParaphrases":["actions","official steps"],"masteryContexts":[{"contextId":"u4_37_measures_meaning","text":"The council took emergency measures to clear the snow from the main roads.","meaning":"actions taken to deal with a problem","wrongMeanings":["calculations made to find the width of a road","plans made to build a longer road","payments made to the workers on a road"]},{"contextId":"u4_37_measures_paraphrase","text":"Safety measures on the new tram line include barriers, warning lights and cameras.","meaning":"actions taken to achieve a result such as safety","wrongMeanings":["sizes that are given for barriers, lights and cameras","prices that are charged for barriers, lights and cameras","rules that forbid barriers, lights and cameras"]}],"situationDistractors":["The tourists bought tickets and boarded the sightseeing bus.","The pilot announced that the flight would land in twenty minutes.","A mechanic washed the car and polished the wheels.","The ferry captain welcomed everyone on board and pointed out the lifeboats.","The air steward served drinks and then collected the empty cups.","A cyclist waited at the traffic lights for the green signal."],"gapDistractors":[{"contextId":"u4_37_measures_gap_1","answer":"measures","wrong":["tickets","uniforms","timetables"]},{"contextId":"u4_37_measures_gap_2","answer":"measures","wrong":["holidays","uniforms","timetables"]},{"contextId":"u4_37_measures_gap_3","answer":"measures","wrong":["holidays","fares","meals"]}],"spellingErrors":["mesures","measurs","meashures","mezures","measuers","meausres"],"masteryPassages":[{"passageId":"u4_37_measures_passage_1","contextId":"u4_37_measures_gap_1","text":"Air pollution in the capital reached dangerous levels last winter. As a result, the authorities took urgent ____, including a ban on older diesel cars in the city centre.","answer":"measures"},{"passageId":"u4_37_measures_passage_2","contextId":"u4_37_measures_gap_2","text":"Too many cyclists were being injured at the roundabout. The council therefore introduced several safety ____: separate cycle lanes, clearer signs and lower speed limits.","answer":"measures"}],"contextDependentParaphrases":[],"wrongParaphrases":["sizes","prices","weights"],"misleadingDistractors":["the sizes of objects, shown in numbers","the amounts of money paid for a service","the instruments used to find the weight of a load"]}]'::jsonb,'[]'::jsonb,'["safety measures","emergency measures","take measures"]'::jsonb,'live'),
('vocab_estimate','estimate','verb','to calculate or judge an amount approximately','[{"senseId":"estimate_1","meaning":"to calculate or judge an amount approximately","acceptedParaphrases":["roughly calculate","judge approximately"],"masteryContexts":[{"contextId":"u4_38_estimate_meaning","text":"Engineers estimate that the new bridge will cost about two hundred million pounds.","meaning":"to calculate approximately","wrongMeanings":["to pay in advance","to announce publicly","to check carefully against a plan"]},{"contextId":"u4_38_estimate_paraphrase","text":"It is difficult to estimate how many cars use this road because there are no counting machines.","meaning":"to judge an amount without exact figures","wrongMeanings":["to list every car on a road exactly","to record the speed of cars on a road","to forbid cars from using a road"]}],"situationDistractors":["The driver counted every passenger as they got on and wrote down the exact number.","The bus company published the exact timetable on its website.","The engineer measured the bridge with a tape and recorded the precise length.","The tourists photographed the old castle from the harbour wall.","A cyclist stopped beside the road to fix a puncture.","The ferry left the harbour at noon and reached the island before dark."],"gapDistractors":[{"contextId":"u4_38_estimate_gap_1","answer":"estimate","wrong":["regret","refuse","forget"]},{"contextId":"u4_38_estimate_gap_2","answer":"estimate","wrong":["regret","refuse","announce"]},{"contextId":"u4_38_estimate_gap_3","answer":"estimate","wrong":["forget","repair","sell"]}],"spellingErrors":["estamate","estimete","esstimate","estimat","astimate","estimite"],"masteryPassages":[{"passageId":"u4_38_estimate_passage_1","contextId":"u4_38_estimate_gap_1","text":"Nobody has counted every traveller who passes through the station. However, officials ____ that about ten thousand people use it on a normal weekday.","answer":"estimate"},{"passageId":"u4_38_estimate_passage_2","contextId":"u4_38_estimate_gap_2","text":"Before they start building, engineers must ____ the cost of the project. They compare similar projects and add a safety margin because the final bill is never exactly known.","answer":"estimate"}],"contextDependentParaphrases":[],"wrongParaphrases":["carefully check","publicly announce","strongly deny"],"misleadingDistractors":["to count exactly how many there are","to guess without any evidence","to give a firm promise about something"],"grammarForms":{"base":"estimate","thirdPerson":"estimates","past":"estimated","pastParticiple":"estimated","ing":"estimating"}}]'::jsonb,'[]'::jsonb,'["estimate the cost","estimate how many","conservatively estimate"]'::jsonb,'live'),
('vocab_regulation','regulation','noun','an official rule made by an authority','[{"senseId":"regulation_1","meaning":"an official rule made by an authority","acceptedParaphrases":["official rule","formal requirement"],"masteryContexts":[{"contextId":"u4_39_regulation_meaning","text":"Under the new regulation, every school bus must have a seat belt for each child.","meaning":"an official rule made by an authority","wrongMeanings":["a polite request made by a driver","an advert printed on a bus","a record kept by a bus company"]},{"contextId":"u4_39_regulation_paraphrase","text":"The airline broke a safety regulation, so it was fined by the aviation authority.","meaning":"an official rule about how something must be done","wrongMeanings":["a private agreement between two airlines","a fee charged to every passenger","a report written by an airline pilot"]}],"situationDistractors":["The driver chose a different route because he wanted to see the coast.","The bus company offered a discount to passengers who travelled on Sundays.","The tourists asked the guide where they could buy a cup of coffee.","The mechanic repaired the brakes while the family waited beside the road.","The taxi driver took a shortcut through the old town.","The cyclist stopped at the traffic lights and waited for the signal to change."],"gapDistractors":[{"contextId":"u4_39_regulation_gap_1","answer":"regulation","wrong":["timetable","holiday","fashion"]},{"contextId":"u4_39_regulation_gap_2","answer":"regulation","wrong":["holiday","weather","fashion"]},{"contextId":"u4_39_regulation_gap_3","answer":"regulation","wrong":["festival","holiday","journey"]}],"spellingErrors":["reguation","regualtion","regulashun","reglation","regulatoin","rgulation"],"wordFamilyForms":[{"form":"regulation","partOfSpeech":"noun","example":"The airline broke a regulation about the weight of hand luggage.","pedagogicallyUseful":true},{"form":"regulate","partOfSpeech":"verb","example":"Governments regulate the number of hours that lorry drivers may work.","pedagogicallyUseful":true},{"form":"regulated","partOfSpeech":"adjective","example":"Taxi fares are strictly regulated in most large cities.","pedagogicallyUseful":true},{"form":"regulatory","partOfSpeech":"adjective","example":"A regulatory body checks that airlines follow the safety rules.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_39_regulation_passage_1","contextId":"u4_39_regulation_gap_1","text":"Airlines may only carry a limited weight of cargo on each flight. This ____ exists to protect passengers, and companies that ignore it can be fined.","answer":"regulation"},{"passageId":"u4_39_regulation_passage_2","contextId":"u4_39_regulation_gap_2","text":"Cyclists in some countries must have a working light on their bike after dark. A police officer can stop anyone who breaks this ____.","answer":"regulation"}],"contextDependentParaphrases":[],"wrongParaphrases":["official report","public holiday","private contract"],"misleadingDistractors":["a set of laws considered together","a habit that a person follows each day","a suggestion that people may ignore"]}]'::jsonb,'["regulate","regulated","regulatory"]'::jsonb,'["safety regulation","strict regulation","new regulation"]'::jsonb,'live'),
('vocab_operate','operate','verb','to control or use a machine, vehicle or system','[{"senseId":"operate_1","meaning":"to control or use a machine, vehicle or system","acceptedParaphrases":["control","work"],"masteryContexts":[{"contextId":"u4_40_operate_meaning","text":"Drivers need a special licence to operate a heavy lorry.","meaning":"to control and use a vehicle","wrongMeanings":["to repair and test a vehicle","to buy and sell a vehicle","to wash and clean a vehicle"]},{"contextId":"u4_40_operate_paraphrase","text":"The pilot learned to operate the aircraft’s flight computer.","meaning":"to use a system correctly","wrongMeanings":["to design a system correctly","to repair a system correctly","to sell a system correctly"]}],"situationDistractors":["The crane stood still beside the quay because the workers had gone home.","A mechanic repaired the engine of the tractor in his workshop.","The engineers designed the new crane on a computer and sent the plans to the factory.","The tourists bought postcards at the kiosk near the harbour.","The ferry arrived at the port and the passengers walked off slowly.","The pilot spoke to the control tower and checked the weather report."],"gapDistractors":[{"contextId":"u4_40_operate_gap_1","answer":"operate","wrong":["sell","paint","photograph"]},{"contextId":"u4_40_operate_gap_2","answer":"operate","wrong":["destroy","paint","deliver"]},{"contextId":"u4_40_operate_gap_3","answer":"operate","wrong":["paint","steal","insure"]}],"spellingErrors":["oparate","operat","operrate","opperate","operete","oporate"],"wordFamilyForms":[{"form":"operate","partOfSpeech":"verb","example":"Pilots must learn how to operate every system in the cockpit.","pedagogicallyUseful":true},{"form":"operator","partOfSpeech":"noun","example":"The bus operator announced a new timetable for the summer.","pedagogicallyUseful":true},{"form":"operation","partOfSpeech":"noun","example":"The safe operation of heavy machinery requires years of training.","pedagogicallyUseful":true},{"form":"operational","partOfSpeech":"adjective","example":"The new airport terminal will become operational in March.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_40_operate_passage_1","contextId":"u4_40_operate_gap_1","text":"Learner pilots begin by practising on a simulator. Only after many hours are they allowed to ____ a real aeroplane with passengers on board.","answer":"operate"},{"passageId":"u4_40_operate_passage_2","contextId":"u4_40_operate_gap_2","text":"Tram drivers must complete a training course before they are allowed to ____ the vehicles. They learn how the brakes, doors and signals work.","answer":"operate"}],"contextDependentParaphrases":[],"wrongParaphrases":["repair","sell","paint"],"misleadingDistractors":["to repair a machine that is not working","to build a machine from separate parts","to sell a machine to a customer"],"grammarForms":{"base":"operate","thirdPerson":"operates","past":"operated","pastParticiple":"operated","ing":"operating"}}]'::jsonb,'["operator","operation","operational"]'::jsonb,'["operate a vehicle","operate machinery","safely operate"]'::jsonb,'live')
